$('enhanced-reveal').oninput=updateEnhancedOverlay;$('scan-image').addEventListener('load',restoreEnhancedReveal);$('enhanced-preview').addEventListener('load',restoreEnhancedReveal);


// These helpers alter only the unsaved context. Saved revision contexts are clones.
function clearCurrentViewingLens(){delete state.context.imageView;$('imageView').value='';restoreImageView();}
function detachCurrentComparisonLens(){if(!state.context.imageView)return;try{const view=JSON.parse(state.context.imageView);view.enhancedComparison=null;state.context.imageView=JSON.stringify(view,null,2);$('imageView').value=state.context.imageView;}catch{clearCurrentViewingLens();}}

// Applies only validated, bounded display settings from a reading context; source bytes never change.
function applyLensOperations(operations){const setters={imageZoomPercent:v=>{zoom=v/100;},imageBrightnessPercent:v=>{$('view-brightness').value=String(v);},imageContrastPercent:v=>{$('view-contrast').value=String(v);},surroundingBackgroundPercent:v=>{$('view-background').value=String(v);},readingTextSizePx:v=>{$('reading-size').value=String(v);},readingLineSpacingPercent:v=>{$('reading-spacing').value=String(v);}};for(const {op,value} of operations)if(Object.hasOwn(setters,op))setters[op](value);sizeImage();updateImageView();updateReadingView();}
function downloadText(text,type,filename){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCsv(){try{readyForExport();downloadText(contextUI.readingsCsv(),'text/csv;charset=utf-8','review-record-'+state.id.split(':').at(-1)+'.csv');notify('Readings index saved. It names each context by ID, version and hash; the JSON review record carries the definitions.');}catch(e){notify(e.message);}}

function renderDiscoveryTrail(){if(!state.context.discoveryTrail&&!document.getElementById('discovery-trail'))return;let box=document.getElementById('discovery-trail');if(!box){box=document.createElement('details');box.id='discovery-trail';document.querySelector('main').prepend(box);}box.replaceChildren();box.hidden=!state.context.discoveryTrail;if(box.hidden)return;const summary=document.createElement('summary');summary.textContent='Search notes carried into this review';const note=document.createElement('p');note.textContent='Self-declared search history. The selected source has not been fetched or verified. No upload permission, identity or approval is established.';const pre=document.createElement('pre');pre.style.whiteSpace='pre-wrap';pre.style.overflowWrap='anywhere';pre.textContent=state.context.discoveryTrail.packet;box.append(summary,note,pre);}

// Native details keeps secondary recovery controls collapsed until requested.
const recoveryTools=document.createElement('details');recoveryTools.id='recovery-tools';recoveryTools.className='recovery-tools';recoveryTools.open=false;
