// Explicit recovery preserves the ordinary draft unless the creator chooses replacement.
const readOnlyHistoryButton=document.createElement('button');readOnlyHistoryButton.type='button';readOnlyHistoryButton.textContent='Download retained history only';readOnlyHistoryButton.className='quiet';recoveryActions.append(readOnlyHistoryButton);
readOnlyHistoryButton.onclick=async()=>{try{const id=state.id,retained=await creatorHistory.readOnlyExport(id);if(state.id!==id)throw Error('Workspace changed during retained history export. Retry.');if(!retained)throw Error('No retained history for this record.');downloadText(retained.text,'application/json','retained-history-'+id.split(':').at(-1)+'.json');notify('Read-only retained branch download requested. No creator save, checkpoint adoption or reconciliation occurred. Preserve any conflicting legacy branch separately. Download completion is not confirmed.');}catch(error){notify(error.message);}};
const recoverHistoryButton=document.createElement('button');recoverHistoryButton.type='button';recoverHistoryButton.textContent='Recover saved creator history';recoverHistoryButton.className='quiet';recoveryActions.append(recoverHistoryButton);
recoverHistoryButton.onclick=async()=>{try{const opening=state,baseline=JSON.stringify(state),loadVersion=++workspaceLoadVersion,retained=await creatorHistory.load(state.id);if(!retained)throw Error('No creator checkpoint retained for this record on this device. Open an exported history bundle.');if(state!==opening||JSON.stringify(state)!==baseline||loadVersion!==workspaceLoadVersion)throw Error('Workspace changed during recovery. Try again.');if(!confirm('Replace this draft with the latest creator save retained on this device? Export unsaved work first if needed.'))return;await creatorHistory.acceptLoaded(retained,async()=>{await adoptBrowserDraftAfterBackup();if(state!==opening||JSON.stringify(state)!==baseline||loadVersion!==workspaceLoadVersion)throw Error('Workspace changed during recovery adoption.');});if(state!==opening||JSON.stringify(state)!==baseline||loadVersion!==workspaceLoadVersion)return;const recovered=retained.state;state=recovered;clearImage();await contextUI.absorbRecord();if(state!==recovered||loadVersion!==workspaceLoadVersion)return;populate();notify('Recovered the latest locally retained creator save. Source image bytes remain separate.');}catch(error){notify(error.message);}};

function capturePendingInputs(){const inputs={};for(const input of document.querySelectorAll('input,textarea,select'))if(input.id&&input.type!=='file')inputs[input.id]={value:String(input.value),checked:input.type==='checkbox'?Boolean(input.checked):null};return inputs;}
function restorePendingInputs(inputs){for(const [id,saved]of Object.entries(inputs)){const input=document.getElementById(id);if(input&&['INPUT','TEXTAREA','SELECT'].includes(input.tagName)&&input.type!=='file'){input.value=saved.value;if(saved.checked!==null&&input.type==='checkbox')input.checked=saved.checked;}}}
const preservedDraftSelect=document.createElement('select');preservedDraftSelect.setAttribute('aria-label','Choose a preserved local draft copy');preservedDraftSelect.hidden=true;const preservedDraftButton=document.createElement('button');preservedDraftButton.type='button';preservedDraftButton.textContent='Download preserved draft recovery';preservedDraftButton.className='quiet';recoveryActions.append(preservedDraftSelect);recoveryActions.append(preservedDraftButton);
preservedDraftButton.onclick=async()=>{try{if(!preservedDraftSelect.value){const rows=await creatorHistory.listDraftBackups();if(!rows.length)throw Error('No catalogued preserved draft copies in the current history store. Earlier browser-storage copies remain separate.');preservedDraftSelect.replaceChildren();const prompt=document.createElement('option');prompt.value='';prompt.textContent='Choose a preserved local copy';preservedDraftSelect.append(prompt);for(const row of rows){const option=document.createElement('option');option.value=row.sha256;option.textContent=row.recordedAt+' · '+row.byteLength+' bytes · '+row.sha256.slice(0,12);preservedDraftSelect.append(option);}preservedDraftSelect.hidden=false;preservedDraftSelect.focus();notify('Choose a preserved local draft copy, then request its recovery download. Labels do not authenticate its author.');return;}const hash=preservedDraftSelect.value,raw=await creatorHistory.readDraftBackup(hash),recovered=await restoreDraft(raw),recoveryText=makeDraftRecovery(recovered,{});await openDraftRecovery(JSON.parse(recoveryText));downloadText(recoveryText,'application/json','preserved-draft-recovery-'+hash.slice(0,12)+'.json');notify('Preserved draft recovery download requested as UNSAVED work. No workspace, creator history or checkpoint changed. Keep private; source files remain separate.');}catch(error){notify(error.message);}};
const draftRecoveryButton=document.createElement('button');draftRecoveryButton.type='button';draftRecoveryButton.textContent='Download draft recovery';draftRecoveryButton.className='quiet';recoveryActions.append(draftRecoveryButton);
draftRecoveryButton.onclick=()=>{try{captureImageView();collect();const pendingInputs=capturePendingInputs();downloadText(makeDraftRecovery(state,pendingInputs),'application/json','draft-recovery-'+state.id.split(':').at(-1)+'.json');notify('Unsaved draft recovery download requested. This is not a verified receipt or creator-history backup. It includes pending text fields; keep it private. Source bytes remain separate.');}catch(error){notify('Draft recovery could not be prepared: '+error.message);}};

// Explicit recovery may adopt a newer shared browser draft only after preserving
// its exact bytes. Later conflicting edits still fail the normal storage guard.
async function adoptBrowserDraftAfterBackup(){try{guardedStorage.assertCurrent(KEY);return;}catch(error){if(error.code!=='STORAGE_CONFLICT')throw error;}const raw=localStorage.getItem(KEY);if(raw!==null){if(creatorHistory.supportsDraftBackups){await creatorHistory.backupDraft(raw);}else{const backupKey=KEY+':preserved-before-recovery:'+await digest(raw),existing=localStorage.getItem(backupKey);if(existing!==null&&existing!==raw)throw Error('Preserved draft recovery copy conflicts. No draft replaced.');localStorage.setItem(backupKey,raw);if(localStorage.getItem(backupKey)!==raw)throw Error('Could not verify preserved browser draft. No draft replaced.');}}guardedStorage.adopt(KEY,raw);}

// Pending feedback wraps the whole asynchronous handler, including context checks.
// Inputs remain editable; existing workspace snapshots and CAS checks still apply.
const pendingSaveControls=['save-revision','save-review','save-resolution','export-cairn','choose-save-location','download-save-copy','export-save-as','export-text','print-cairn'];
async function runPendingSave(control,operation){
 if(pendingSaveUI){notify('Saving… the previous operation is still in progress.');return;}
 const ticket={control,previousDraftStatus:$('save-state').textContent,lastDraftStatus:null,previous:pendingSaveControls.map(id=>({id,disabled:Boolean($(id).disabled)}))};pendingSaveUI=ticket;
 $('save-state').setAttribute('role','status');$('save-state').setAttribute('aria-live','polite');$('save-state').textContent='Saving…';control.setAttribute('aria-busy','true');
 for(const item of ticket.previous)$(item.id).disabled=true;notify('Saving…');
 try{return await operation();}catch(error){notify(error.message||'Save did not complete. Keep unsaved work.');}
 finally{if(pendingSaveUI===ticket){pendingSaveUI=null;control.setAttribute('aria-busy','false');for(const item of ticket.previous)$(item.id).disabled=item.disabled;const outcomeStatus=$('save-state').textContent;$('save-state').textContent=outcomeStatus&&outcomeStatus!=='Saving…'?outcomeStatus:ticket.lastDraftStatus||ticket.previousDraftStatus||'Operation finished. See the message for its result.';if(String($('toast').textContent||'').startsWith('Saving…'))notify(control.id==='choose-save-location'?$('save-location-status').textContent:$('save-error').hidden===false?$('save-error').textContent:'Save operation finished. Check the result message.');}}
}
for(const id of ['save-revision','save-review','save-resolution','export-cairn','choose-save-location']){const control=$(id),handler=control.onclick;control.onclick=(...args)=>runPendingSave(control,()=>handler(...args));}

if(practiceId!==null){if(practiceWarning)notify('Practice link refused: '+practiceWarning);else if(!loadedDraftRaw)await example(practiceId);}

// Explicit hOCR adoption uses the same draft, revision and creator-history machinery.
hocrUI=installHocrUI({getSource:()=>state.sourceImage,getPassageRecords:()=>({revisions:state.revisions,reviews:state.reviews}),getSelection:()=>hocrPin(state.context),getSavedReading:()=>{
 collect();const saved=state.revisions.find(r=>r.id===state.activeRevisionId)||state.revisions.at(-1);
 if(!saved||JSON.stringify(state.draft)!==JSON.stringify(saved.reading))throw Error('Save the current reading before exporting its hOCR proposal.');
 const pin=hocrPin(saved.context);
 if(!pin?.hocrSha256)throw Error('Selected saved reading has no hOCR provenance.');
 return {pin,proposed:saved.reading.proposed,revisionId:saved.id};
},selectWord:({word,page,hocr})=>{
 if(historyBusy)throw Error('Wait for the current save to finish before changing words.');
 collect();const saved=state.revisions.find(r=>r.id===state.activeRevisionId)||state.revisions.at(-1);
 const previousPin=hocrPin(state.context),untouchedWord=previousPin&&previousPin.sourceSha256===state.sourceImage.sha256&&previousPin.hocrSha256===hocr.sha256&&state.draft.original===previousPin.originalWord&&state.draft.proposed===state.draft.original&&state.draft.reason===''&&state.draft.uncertainty==='not_assessed'&&!state.draft.assistance&&state.context.method==='Human review of a highlighted hOCR word against the source image.'&&state.context.sourceFile===state.sourceImage.name&&state.context.locator==='hOCR page '+(previousPin.pageIndex+1)+' ('+previousPin.pageId+'), word '+previousPin.wordId+', bbox '+previousPin.bbox.join(' ');
 if(state.draft.original&&!untouchedWord&&(!saved||JSON.stringify(state.draft)!==JSON.stringify(saved.reading)))throw Error('Save this reading before selecting another word. To keep unfinished work without saving a proposal, use More tools / full form and download draft recovery.');
 const existing=state.revisions.findLast(r=>{const pin=hocrPin(r.context);return pin?.hocrSha256===hocr.sha256&&pin.sourceSha256===state.sourceImage.sha256&&pin.pageId===page.id&&pin.wordId===word.id&&JSON.stringify(pin.bbox)===JSON.stringify(word.box);});
 if(existing){state.activeRevisionId=existing.id;state.draft=structuredClone(existing.reading);state.context=structuredClone(existing.context);populate();showPanel('reading');return;}
 state.draft={original:word.text,proposed:word.text,contributor:state.draft.contributor||'',uncertainty:'not_assessed',reason:''};
 state.context.sourceFile=state.sourceImage.name;
 state.context.locator='hOCR page '+(page.index+1)+' ('+page.id+'), word '+word.id+', bbox '+word.box.join(' ');
 state.context.hocr={operation:'Human review of hOCR word; no recognition or correction applied automatically',hocrFile:hocr.name,hocrSha256:hocr.sha256,hocrBytes:hocr.bytes,pageId:page.id,pageIndex:page.index,wordId:word.id,originalWord:word.text,bbox:word.box,ocrConfidence:word.confidence,sourceSha256:state.sourceImage.sha256,identity:'Local image dimensions matched; correspondence asserted by contributor, not independently verified'};
 state.context.method='Human review of a highlighted hOCR word against the source image.';
 populate();showPanel('reading');
}});

if(recoveryRaw===null)void restoreBundledPractice();

// Module manifests are untrusted task data. Apply only to an untouched separate workspace.
if(practiceParams.has('moduleTicket'))receiveModuleTask({href:location.href,hash:digest,notify,apply:async ({module,item,file,sha256,manifestSha256})=>{
 collect();
 const untouched=()=>!state.sourceImage&&!state.revisions.length&&!state.reviews.length&&!Object.values(state.draft).some(v=>typeof v==='string'&&v.trim()&&v!=='not_assessed')&&!Object.values(state.context).some(v=>typeof v==='string'?v.trim():v!=null)&&!state.modelRuns.length&&!state.connections.length;
 if(!separateWorkspace||!untouched())throw Error('This workspace already contains work. Open the task in a new workspace.');
 const openingState=state,openingDraft=JSON.stringify(state.draft),openingContext=JSON.stringify(state.context);
 await $('source-image').onchange({target:{files:[file],value:''}});
 collect();
 if(state!==openingState||state.sourceImage?.sha256!==sha256)throw Error('The selected source could not be applied.');
 const contextWithoutSource={...state.context};delete contextWithoutSource.sourceFile;delete contextWithoutSource.reviewBasis;
 const initialContext={...JSON.parse(openingContext)};delete initialContext.sourceFile;delete initialContext.reviewBasis;
 if(JSON.stringify(state.draft)!==openingDraft||JSON.stringify(contextWithoutSource)!==JSON.stringify(initialContext))throw Error('Work changed during source loading. Source opened, but your fields were preserved.');
 state.context.title=module.title+' · '+item.title;state.context.locator=item.locator;state.context.reviewBasis=item.baselineKind;
 state.context.dataModule={schema:module.schema,id:module.id,manifestSha256,taskId:item.id,question:item.question,sourcePath:item.source.path,declaredSource:{...item.source},selectedSourceName:file.name,measuredBytes:file.size,sourceSha256:sha256,reuseStatement:module.reuseStatement,baselineKind:item.baselineKind,region:item.region,verification:'Selected source bytes checked; supplied claims, reuse and reading kind unverified'};
 state.draft.original=item.baseline;state.draft.proposed=item.baseline;
 populate();persist();
 document.dispatchEvent(new CustomEvent('reckoner-module-region',{detail:{box:item.region,question:item.question}}));
 document.dispatchEvent(new CustomEvent('reckoner-workspace-opened'));
 notify('Module task opened. Check the supplied reading against the source, add your interpretation and reason, then save.');
}});

function renderModuleQuestion(){
 let line=$('module-current-question');const task=state.context.dataModule;
 if(!task){if(line)line.remove();return;}
 if(!line){line=document.createElement('p');line.id='module-current-question';line.setAttribute('role','note');$('reading').prepend(line);}
 line.textContent=typeof task.question==='string'?task.question:'';line.dataset.region=JSON.stringify(task.region??null);
}
